1	/**
2	 * @module useSetores
3	 *
4	 * Hook de gestão de setores de produtos. Busca setores ativos,
5	 * agrega contagem de produtos ativos por setor e expõe operações
6	 * de criar, mover itens, excluir setor e atualizar produto.
7	 *
8	 * REGRA INVIOLÁVEL: nunca altera produtos com ativo=false em produtos_master.
9	 */
10	
11	import { useQuery, useQueryClient } from '@tanstack/react-query';
12	import { supabase } from '@/integrations/supabase/client';
13	
14	/** Setor com contagem de produtos ativos vinculados. */
15	export interface SetorComContagem {
16	  nome: string;
17	  itensAtivos: number;
18	}
19	
20	/** Resultado estruturado de operações de mutação. */
21	export interface SetorResult {
22	  ok: boolean;
23	  error?: string;
24	  movidos?: number;
25	}
26	
27	/**
28	 * Busca setores ativos e agrega contagem de produtos ativos por setor.
29	 *
30	 * Usa uma única query de produtos_master (todos com ativo=true) e
31	 * conta client-side, evitando N+1 queries ao banco.
32	 */
33	async function fetchSetoresComContagem(): Promise<SetorComContagem[]> {
34	  const [setoresRes, produtosRes] = await Promise.all([
35	    // @ts-expect-error tabela 'setores' não está nos tipos gerados ainda
36	    supabase.from('setores').select('nome').eq('ativo', true).order('nome'),
37	    supabase
38	      .from('produtos_master')
39	      .select('setor')
40	      .eq('ativo', true),
41	  ]);
42	
43	  if (setoresRes.error) throw setoresRes.error;
44	  if (produtosRes.error) throw produtosRes.error;
45	
46	  const setoresData = (setoresRes.data ?? []) as { nome: string }[];
47	  const produtosData = (produtosRes.data ?? []) as { setor: string | null }[];
48	
49	  // Agregar contagem de produtos por nome de setor (client-side)
50	  const contagemPorSetor = new Map<string, number>();
51	  for (const produto of produtosData) {
52	    if (produto.setor) {
53	      contagemPorSetor.set(
54	        produto.setor,
55	        (contagemPorSetor.get(produto.setor) ?? 0) + 1,
56	      );
57	    }
58	  }
59	
60	  return setoresData.map((s) => ({
61	    nome: s.nome,
62	    itensAtivos: contagemPorSetor.get(s.nome) ?? 0,
63	  }));
64	}
65	
66	/**
67	 * Hook de gestão de setores de produtos.
68	 *
69	 * Fornece lista de setores ativos com contagem de itens e funções
70	 * para criar, mover itens entre setores, excluir e atualizar produto.
71	 */
72	export function useSetores() {
73	  const queryClient = useQueryClient();
74	
75	  const { data, isLoading, refetch } = useQuery<SetorComContagem[]>({
76	    queryKey: ['setores-gestao'],
77	    queryFn: fetchSetoresComContagem,
78	  });
79	
80	  const setores: SetorComContagem[] = data ?? [];
81	
82	  /**
83	   * Cria um novo setor (normalizado para UPPERCASE).
84	   * Se existir inativo, reativa. Se existir ativo, retorna erro de duplicata.
85	   */
86	  async function criarSetor(nome: string): Promise<SetorResult> {
87	    const norm = nome.trim().toUpperCase();
88	    if (!norm) return { ok: false, error: 'Informe um nome.' };
89	
90	    // Buscar setor existente (ativo ou inativo)
91	    const { data: existente, error: buscaError } = await (
92	      // @ts-expect-error tabela 'setores' não está nos tipos gerados ainda
93	      supabase.from('setores').select('nome, ativo').eq('nome', norm).maybeSingle()
94	    );
95	
96	    if (buscaError) return { ok: false, error: buscaError.message };
97	
98	    if (existente) {
99	      if ((existente as { nome: string; ativo: boolean }).ativo) {
100	        return { ok: false, error: 'Esse setor já existe.' };
101	      }
102	      // Reativar setor inativo
103	      const { error: reativarError } = await (
104	        // @ts-expect-error tabela 'setores' não está nos tipos gerados ainda
105	        supabase.from('setores').update({ ativo: true }).eq('nome', norm)
106	      );
107	      if (reativarError) return { ok: false, error: reativarError.message };
108	      await queryClient.invalidateQueries({ queryKey: ['setores-gestao'] });
109	      return { ok: true };
110	    }
111	
112	    // Inserir novo setor
113	    const { error: insertError } = await (
114	      // @ts-expect-error tabela 'setores' não está nos tipos gerados ainda
115	      supabase.from('setores').insert({ nome: norm, ativo: true })
116	    );
117	    if (insertError) return { ok: false, error: insertError.message };
118	
119	    await queryClient.invalidateQueries({ queryKey: ['setores-gestao'] });
120	    return { ok: true };
121	  }
122	
123	  /**
124	   * Move todos os produtos ativos do setor 'de' para o setor 'para'.
125	   * Nunca toca em produtos com ativo=false.
126	   */
127	  async function moverItens(de: string, para: string): Promise<SetorResult> {
128	    if (!de || !para) return { ok: false, error: 'Informe os dois setores.' };
129	    if (de === para) return { ok: false, error: 'Setores de origem e destino são iguais.' };
130	
131	    // Contar quantos serão movidos antes do update
132	    const { count, error: countError } = await supabase
133	      .from('produtos_master')
134	      .select('id', { count: 'exact', head: true })
135	      .eq('setor', de)
136	      .eq('ativo', true);
137	
138	    if (countError) return { ok: false, error: countError.message };
139	
140	    const movidos = count ?? 0;
141	
142	    if (movidos === 0) {
143	      await queryClient.invalidateQueries({ queryKey: ['setores-gestao'] });
144	      return { ok: true, movidos: 0 };
145	    }
146	
147	    const { error: updateError } = await supabase
148	      .from('produtos_master')
149	      .update({ setor: para })
150	      .eq('setor', de)
151	      .eq('ativo', true);
152	
153	    if (updateError) return { ok: false, error: updateError.message };
154	
155	    await queryClient.invalidateQueries({ queryKey: ['setores-gestao'] });
156	    return { ok: true, movidos };
157	  }
158	
159	  /**
160	   * Exclui um setor. Bloqueia se houver produtos ativos apontando para ele.
161	   * Produtos inativos que ainda referenciam o nome são deixados intocados.
162	   */
163	  async function excluirSetor(nome: string): Promise<SetorResult> {
164	    // Contar produtos ativos com esse setor
165	    const { count, error: countError } = await supabase
166	      .from('produtos_master')
167	      .select('id', { count: 'exact', head: true })
168	      .eq('setor', nome)
169	      .eq('ativo', true);
170	
171	    if (countError) return { ok: false, error: countError.message };
172	
173	    const total = count ?? 0;
174	    if (total > 0) {
175	      return {
176	        ok: false,
177	        error: `Mova os ${total} itens ativos antes de excluir.`,
178	      };
179	    }
180	
181	    const { error: deleteError } = await (
182	      // @ts-expect-error tabela 'setores' não está nos tipos gerados ainda
183	      supabase.from('setores').delete().eq('nome', nome)
184	    );
185	    if (deleteError) return { ok: false, error: deleteError.message };
186	
187	    await queryClient.invalidateQueries({ queryKey: ['setores-gestao'] });
188	    return { ok: true };
189	  }
190	
191	  /**
192	   * Atualiza setor e unidade_medida de um produto ativo pelo id.
193	   * Nunca toca em outros campos nem em produtos inativos.
194	   */
195	  async function atualizarProdutoSetorUnidade(
196	    produtoId: number,
197	    setor: string,
198	    unidade: string,
199	  ): Promise<SetorResult> {
200	    const { error } = await supabase
201	      .from('produtos_master')
202	      .update({ setor, unidade_medida: unidade })
203	      .eq('id', produtoId);
204	
205	    if (error) return { ok: false, error: error.message };
206	
207	    await queryClient.invalidateQueries({ queryKey: ['setores-gestao'] });
208	    return { ok: true };
209	  }
210	
211	  return {
212	    setores,
213	    isLoading,
214	    refetch,
215	    criarSetor,
216	    moverItens,
217	    excluirSetor,
218	    atualizarProdutoSetorUnidade,
219	  };
220	}
